INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(44111, 'Leviticus 21:23', 'Leviticus', 21, 23, 'خو په دې خاطر چې په هغه کې جسماني عیب دی، هغه دې سپېڅلې پردې او د قربانۍ ځای ته نژدې رانه شي او زما سپېڅلی ځای او هرڅه چې په کې دي هغه دې نه ناپاکه کوي، ځکه چې زه څښتن یم او کاهنان سپېڅلي کوم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus21_verse_23.mp3', '', 1761754199, 1761754199),
(44112, 'Leviticus 21:24', 'Leviticus', 21, 24, 'نو موسی دا هرڅه هارون او د هغه زامنو او ټولو اسراییلیانو ته وویل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus21_verse_24.mp3', '', 1761754199, 1761754199),
(44113, 'Exodus 37:1', 'Exodus', 37, 1, 'بزل ییل د اکاسۍ د لرګي څخه د لوظ صندوق جوړ کړ چې یو متر او لس سانتي اوږد ؤ، پنځه شپېته سانتي پلن ؤ او پنځه شپېته سانتي لوړ ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_1.mp3', '', 1761754199, 1761754199),
(44114, 'Exodus 37:2', 'Exodus', 37, 2, 'د هغه منځنۍ او باندینۍ برخې ته یې د سوچه سرو زرو پوښ ورکړ او د هغه ګردچاپېره څنډې یې د سرو زرو څخه جوړې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_2.mp3', '', 1761754199, 1761754199),
(44115, 'Exodus 37:3', 'Exodus', 37, 3, 'د هغه دپاره یې څلور د سرو زرو کړۍ ګانې جوړې کړې او د هغه په څلورو پایو باندې یې وتړلې، چې دوه کړۍ ګانې یې یوې خوا او دوه یې بلې خوا ته وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_3.mp3', '', 1761754199, 1761754199),
(44116, 'Exodus 37:4', 'Exodus', 37, 4, 'بیا هغه د اکاسۍ د لرګي څخه میلې جوړې کړې او د سرو زرو پوښ یې ورته ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_4.mp3', '', 1761754199, 1761754199),
(44117, 'Exodus 37:5', 'Exodus', 37, 5, 'میلې یې هغو کړیو ته د وړلو دپاره ورننویستلې چې د صندوق په څنګونو کې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_5.mp3', '', 1761754199, 1761754199),
(44118, 'Exodus 37:6', 'Exodus', 37, 6, 'د سوچه سرو زرو څخه یې د صندوق سرپوښ چې کفاره ورباندې ادا کیږي، جوړ کړ چې یو متر او لس سانتي اوږد ؤ او پنځه شپېته سانتي پلن ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_6.mp3', '', 1761754199, 1761754199),
(44119, 'Exodus 37:7', 'Exodus', 37, 7, 'بیا هغه د سرپوښ په خواوو باندې د ټکول شویو سرو زرو څخه دوه اسماني مخلوقات جوړ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_7.mp3', '', 1761754199, 1761754199),
(44120, 'Exodus 37:8', 'Exodus', 37, 8, 'یو یې په یوې خوا او دوهم ‎ یې په بلې خوا باندې جوړ کړ، په دوو خواوو باندې یې د سرپوښ سره اسماني مخلوقات د سرو زرو د یوې ټوټې څخه جوړ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_8.mp3', '', 1761754199, 1761754199),
(44121, 'Exodus 37:9', 'Exodus', 37, 9, 'د اسماني مخلوقاتو وزرونه د دې دپاره پورته خپاره وو چې په سرپوښ باندې سیوری وکړي. هغوی یو بل ته مخامخ وو او د سرپوښ خواته یې کتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_9.mp3', '', 1761754199, 1761754199),
(44122, 'Exodus 37:10', 'Exodus', 37, 10, 'بزل ییل د اکاسۍ د لرګي څخه یو داسې مېز جوړ کړ چې نوي سانتي اوږد ؤ، پنځه څلوېښت سانتي پلن ؤ او پنځه شپېته سانتي لوړ ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_10.mp3', '', 1761754199, 1761754199),
(44123, 'Exodus 37:11', 'Exodus', 37, 11, 'بیا یې هغه ته د سوچه سرو زرو پوښ ورکړ او د هغه ګردچاپېره څنډې یې د سرو زرو څخه جوړې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_11.mp3', '', 1761754199, 1761754199),
(44124, 'Exodus 37:12', 'Exodus', 37, 12, 'همدارنګه د هغه ګردچاپېره یې یو چوکاټ جوړ کړ چې پراخوالی یې نیمه لوېشت ؤ او په چوکاټ باندې یې د سرو زرو څنډه جوړه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_12.mp3', '', 1761754199, 1761754199),
(44125, 'Exodus 37:13', 'Exodus', 37, 13, 'هغه د مېز دپاره څلور د سرو زرو کړۍ ګانې جوړې کړې او په هغو څلورو کنجونو کې یې وتړلې چېرته چې څلور پایې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_13.mp3', '', 1761754199, 1761754199),
(44126, 'Exodus 37:14', 'Exodus', 37, 14, 'کړۍ ګانې چوکاټ ته نژدې وې، د دې دپاره چې هغه میلې ونیسي چې د مېز په وړلو کې ورڅخه کار اخیستل کېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_14.mp3', '', 1761754199, 1761754199),
(44127, 'Exodus 37:15', 'Exodus', 37, 15, 'د مېز د وړلو میلې د اکاسۍ د لرګي څخه جوړې شوې وې او د سرو زرو پوښ ورته ورکړل شوی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_15.mp3', '', 1761754199, 1761754199),
(44128, 'Exodus 37:16', 'Exodus', 37, 16, 'هغه ټول شیان چې په مېز باندې ایښودل کېدل یعنې کاسې، قابونه او د څښلو د نذرانو د تویولو دپاره منګي او جامونه د سوچه سرو زرو څخه جوړ شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_16.mp3', '', 1761754199, 1761754199),
(44129, 'Exodus 37:17', 'Exodus', 37, 17, 'بزل ییل د سوچه سرو زرو څخه یو څراغدان جوړ کړ او د هغه پایه او میله، د هغه د پیالو په شان ګلان، غوټۍ ګانې او ګلپاڼې یې د ټکول شویو سرو زرو څخه جوړ کړل. هغه ټول شیان د یوې ټوټې سرو زرو څخه جوړ شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_17.mp3', '', 1761754199, 1761754199),
(44130, 'Exodus 37:18', 'Exodus', 37, 18, 'شپږ څانګې د څراغدان د څنګونو څخه غزېدلې وې، یعنې درې د یو څنګ څخه او درې د بل څنګ څخه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_18.mp3', '', 1761754199, 1761754199),
(44131, 'Exodus 37:19', 'Exodus', 37, 19, 'درې پیالې چې شکلونه یې د بادام د ګل په شان وو، د غوټیو او ګلپاڼو سره په یوې څانګې باندې وې، درې په بلې څانګې باندې او په همدې ډول د شپږو واړو څانګو دپاره وې چې د څراغدان څخه غزېدلې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_19.mp3', '', 1761754199, 1761754199),
(44132, 'Exodus 37:20', 'Exodus', 37, 20, 'په خپله په څراغدان باندې څلور د بادام د ګل په شان پیالې وې، د غوټۍ ګانو او ګلپاڼو سره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_20.mp3', '', 1761754199, 1761754199),
(44133, 'Exodus 37:21', 'Exodus', 37, 21, 'یوه غوټۍ د څانګو د اولې جوړې لاندې وه چې د څراغدان څخه غزېدلې وه، دوهمه غوټۍ د دوهمې جوړې لاندې وه او درېمه غوټۍ د درېمې جوړې لاندې وه یعنې ټولې شپږ څانګې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_21.mp3', '', 1761754199, 1761754199),
(44134, 'Exodus 37:22', 'Exodus', 37, 22, 'غوټۍ ګانې، څانګې او څراغدان د ټکول شویو سوچه سرو زرو د یوې ټوټې څخه جوړ شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_22.mp3', '', 1761754199, 1761754199),
(44135, 'Exodus 37:23', 'Exodus', 37, 23, 'د څراغدان دپاره یې اووه څراغونه جوړ کړل او پلته پاکوونکي او پتنوسونه یې د سوچه سرو زرو څخه جوړ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_23.mp3', '', 1761754199, 1761754199),
(44136, 'Exodus 37:24', 'Exodus', 37, 24, 'هغه د څراغدان او د هغه د ټول سامان په جوړولو کې د څلوردېرشو کیلو ګرامه سوچه سرو زرو څخه کار واخیست.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_24.mp3', '', 1761754199, 1761754199),
(44137, 'Exodus 37:25', 'Exodus', 37, 25, 'بزل ییل د اکاسۍ د لرګي څخه د خوشبویۍ د سوځولو دپاره د قربانۍ یو ځای جوړ کړ. هغه څلور کنجه ؤ، پنځه څلوېښت سانتي اوږد ؤ او پنځه څلوېښت سانتي پلن ؤ او نوي سانتي لوړ ؤ. د هغې ښکرونه چې په څلورو کنجونو کې وو، هغه د قربانۍ د ځای سره د یوې ټوټې لرګي څخه جوړ شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_25.mp3', '', 1761754199, 1761754199),
(44138, 'Exodus 37:26', 'Exodus', 37, 26, 'د هغې پاسنۍ برخې، څلور واړو خواو او ښکرونو ته یې د سرو زرو پوښ ورکړ او د هغه ګردچاپېره څنډه یې د سرو زرو څخه جوړه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_26.mp3', '', 1761754199, 1761754199),
(44139, 'Exodus 37:27', 'Exodus', 37, 27, 'د څنډې لاندې د قربانۍ د ځای دپاره یې دوه د سرو زرو کړۍ ګانې جوړې کړې، یعنې په دواړو خواو باندې یې یوه یوه جوړه کړه چې هغه میلې ونیسي چې د هغې په وړلو کې ورڅخه کار اخیستل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_27.mp3', '', 1761754199, 1761754199),
(44140, 'Exodus 37:28', 'Exodus', 37, 28, 'هغه میلې د اکاسۍ د لرګي څخه جوړې کړې او د سرو زرو پوښ یې ورته ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_28.mp3', '', 1761754199, 1761754199),
(44141, 'Exodus 37:29', 'Exodus', 37, 29, 'همدارنګه بزل ییل د مسح کولو دپاره سپېڅلي تېل او د خوشبویۍ دپاره سوچه مسالې جوړې کړې لکه څنګه چې یو عطر جوړوونکی یې جوړوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus37_verse_29.mp3', '', 1761754199, 1761754199),
(44142, 'Ezekiel 30:1', 'Ezekiel', 30, 1, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_1.mp3', '', 1761754199, 1761754199),
(44143, 'Ezekiel 30:2', 'Ezekiel', 30, 2, '«ای فاني انسانه، نبوت وکړه او مصریانو ته ووایه چې زه څښتن تعالی داسې وایم: ‹وکړئ ژړا او انګولا! ده راروانه یو وېرېدونکې ورځ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_2.mp3', '', 1761754199, 1761754199),
(44144, 'Ezekiel 30:3', 'Ezekiel', 30, 3, 'ځکه رانژدې ده هغه ورځ، چې کوم به زه عمل د تورو ورېځو ورځ ده قومونو ته د مصیبت ورځ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_3.mp3', '', 1761754199, 1761754199),
(44145, 'Ezekiel 30:4', 'Ezekiel', 30, 4, 'وي به په مصر کې جنګ او لوی مصیبت په ایتوپیا کې ډېر خلک به ووژل شي مصر کې شي به لوټ شتمني د هغه او شي به بدل په کنډوالو باندې›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_4.mp3', '', 1761754199, 1761754199),
(44146, 'Ezekiel 30:5', 'Ezekiel', 30, 5, 'په دې جنګ کې به په پیسو اخیستل شوي عسکر د ایتوپیا، لیبیا، لیدیا، د هغه سره نښتي هېوادونه، کوب او حتی زما د خپل قوم نه به هم ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_5.mp3', '', 1761754199, 1761754199),
(44147, 'Ezekiel 30:6', 'Ezekiel', 30, 6, '«څښتن داسې وایي: ‹په شمال کې د مجدل نه، په جنوب کې تر اسوانه پورې، د مصر ټول ملاتړ کوونکي به په جنګ کې ووژل شي. په کومو عسکرو چې مصریان ورباندې مغروره وو، د هغوی دغه غرور به له منځه لاړ شي. ما څښتن تعالی داسې ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_6.mp3', '', 1761754199, 1761754199),
(44148, 'Ezekiel 30:7', 'Ezekiel', 30, 7, 'دا وطن به په نړۍ کې د ټولو نه زیات وران او ویجاړ شي او د دې وطن ټول ښارونه به د نورو ښارونو په پرتله په کنډوالو باندې بدل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_7.mp3', '', 1761754199, 1761754199),
(44149, 'Ezekiel 30:8', 'Ezekiel', 30, 8, 'کله چې زه مصر ته اور واچوم او د هغه ټول ملاتړ کوونکي ووژل شي، نو بیا به مصریان پوه شي چې زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_8.mp3', '', 1761754199, 1761754199),
(44150, 'Ezekiel 30:9', 'Ezekiel', 30, 9, 'کله چې هغه ورځ راورسیږي او مصر له منځه لاړ شي، نو زه به په کشتۍ‌ګانو کې استازي ولېږم چې د ایتوپیا بې‌خبره خلک سخت ووېروي. ګوره، هغه ورځ راروانه ده!›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_9.mp3', '', 1761754199, 1761754199),
(44151, 'Ezekiel 30:10', 'Ezekiel', 30, 10, 'څښتن تعالی داسې وایي: ‹زه به د بابل د پاچا نبوکدنصر په وسیله د مصر شتمني له منځه یوسم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_10.mp3', '', 1761754199, 1761754199),
(44152, 'Ezekiel 30:11', 'Ezekiel', 30, 11, 'هغه او د هغه ډېر بې‌رحمه لښکر به راشي او د مصر هېواد به وران او ویجاړ کړي. هغوی به د خپلو تورو سره په مصر باندې حمله وکړي او هغه هېواد به د مړو نه ډک کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_11.mp3', '', 1761754199, 1761754199),
(44153, 'Ezekiel 30:12', 'Ezekiel', 30, 12, 'زه به د نیل سیند وچ کړم او د مصر واک او اختیار به بدکارو خلکو ته ورکړم. زه به په پرديو خلکو باندې ټول وطن وران او ویجاړ کړم. ما څښتن داسې ویلي دي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_12.mp3', '', 1761754199, 1761754199),
(44154, 'Ezekiel 30:13', 'Ezekiel', 30, 13, 'څښتن تعالی داسې وایي: ‹زه به بتان او د ممفیس غلط خدایان له منځه یوسم. په مصر کې به نور پاچا نه وي چې په هغه باندې حکومت وکړي او زه به د هېواد ټول خلک ووېروم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_13.mp3', '', 1761754199, 1761754199),
(44155, 'Ezekiel 30:14', 'Ezekiel', 30, 14, 'زه به د مصر جنوبي سیمه فتروس وران او ویجاړ کړم او د صوعن ښار چې په شمال کې دی، هغه به وسوځوم. زه به د طیبس د ښار خلکو ته سزا ورکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_14.mp3', '', 1761754199, 1761754199),
(44156, 'Ezekiel 30:15', 'Ezekiel', 30, 15, 'زه به د پلوسیوم په ښار باندې چې د مصر قوي کلا ده، خپل قهر نازل کړم. زه به د تیبس ډېر خلک له منځه یوسم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_15.mp3', '', 1761754199, 1761754199),
(44157, 'Ezekiel 30:16', 'Ezekiel', 30, 16, 'زه به مصر ته اور واچوم او د پلوسیوم ښار به په عذاب باندې اخته شي. د طیبس د ښار دېوالونه به راوغورځیږي او دښمن به په رڼا ورځ په ممفیس باندې حمله وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_16.mp3', '', 1761754199, 1761754199),
(44158, 'Ezekiel 30:17', 'Ezekiel', 30, 17, 'د اون او فیبست ځوانان به په جنګ کې مړه شي او د دې ښارونو پاتې خلک به د اسیرانو په توګه بوتلل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_17.mp3', '', 1761754199, 1761754199),
(44159, 'Ezekiel 30:18', 'Ezekiel', 30, 18, 'کله چې زه د مصر قدرت مات کړم او د مصر هغه قوت چې هغوی ورباندې مغروره وو، له منځه یوسم، نو د تحفنحیس په ښار باندې به توره تیاره راشي. مصر به په ورېځو باندې پټ شي او د دې ښارونو خلک به د اسیرانو په توګه بوتلل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_18.mp3', '', 1761754199, 1761754199),
(44160, 'Ezekiel 30:19', 'Ezekiel', 30, 19, 'کله چې زه مصر ته داسې سزا ورکړم، نو هغوی به پوه شي چې زه څښتن یم.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_19.mp3', '', 1761754199, 1761754199),
(44161, 'Ezekiel 30:20', 'Ezekiel', 30, 20, 'زمونږ د جلاوطنۍ په یوولسم کال د لومړۍ میاشتې په اوومه ورځ څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_20.mp3', '', 1761754199, 1761754199),
(44162, 'Ezekiel 30:21', 'Ezekiel', 30, 21, '«ای فاني انسانه، ما د مصر د پاچا فرعون مټ مات کړی دی. ګوره، د مات مټ جوړوونکی نشته چې په مټ باندې یې پټۍ کېږدي او هغه وتړي چې جوړ شي او دومره قوي شي چې وکولای شي بیا توره په لاس کې ونیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_21.mp3', '', 1761754199, 1761754199),
(44163, 'Ezekiel 30:22', 'Ezekiel', 30, 22, 'نو اوس زه څښتن تعالی داسې وایم: ‹زه د مصر د پاچا فرعون په ضد یم. زه به د هغه دواړه مټې ماتي کړم، د هغه روغ مټ او هغه مټ چې پخوا مات شوی ؤ، ترڅو د هغه د لاس نه توره ولویږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_22.mp3', '', 1761754199, 1761754199),
(44164, 'Ezekiel 30:23', 'Ezekiel', 30, 23, 'زه به مصریان د نړۍ په قومونو او هېوادنو کې خواره واره کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_23.mp3', '', 1761754199, 1761754199),
(44165, 'Ezekiel 30:24', 'Ezekiel', 30, 24, 'بیا به د بابل د پاچا مټې قوي کړم او خپله توره به د هغه په لاس کې ورکړم. خو د فرعون مټې به ماتې کړم، ترڅو لکه د یو زخمي په شان چې مرګ ته نژدې وي، د بابل د پاچا په مخکې زګېروي وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_24.mp3', '', 1761754199, 1761754199),
(44166, 'Ezekiel 30:25', 'Ezekiel', 30, 25, 'هو، زه به هغه کمزوری کړم او د بابل پاچا به قوي کړم. کله چې زه هغه ته خپله توره ورکړم چې د مصر په وړاندې ورڅخه کار واخلي، نو مصریان به په دې پوه شي چې زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_25.mp3', '', 1761754199, 1761754199),
(44167, 'Ezekiel 30:26', 'Ezekiel', 30, 26, 'زه به مصریان د نړۍ په قومونو او هېوادنو کې خواره واره کړم. بیا به هغوی په دې پوه شي چې زه څښتن یم.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel30_verse_26.mp3', '', 1761754199, 1761754199),
(44168, 'Deuteronomy 7:1', 'Deuteronomy', 7, 1, 'کله چې ستاسو څښتن خدای تاسو هغې خاورې ته ورولي چې تاسو به یې ونیسئ، نو هغه به ډېر قومونه ستاسو له مخې څخه لېرې کړي یعنې حیتیان، جرجاشیان، اموریان، کنعانیان، فرزیان، حویان او یبوسیان. دا اووه قومونه ستاسو څخه لوی او ډېر قوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_1.mp3', '', 1761754199, 1761754199),
(44169, 'Deuteronomy 7:2', 'Deuteronomy', 7, 2, 'کله چې ستاسو څښتن خدای دغه قومونه تاسو ته په لاس درکړل او تاسو هغوی ته ماتې ورکړه، نو هغوی ټول باید ووژنئ. د هغوی سره کوم تړون مه کوئ او نه ورباندې رحم وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_2.mp3', '', 1761754199, 1761754199),
(44170, 'Deuteronomy 7:3', 'Deuteronomy', 7, 3, 'د هغوی سره ودونه مه کوئ. خپلې لورګانې د هغوی زامنو ته مه ورکوئ او د هغوی لورګانې خپلو زامنو ته مه کوئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_3.mp3', '', 1761754199, 1761754199),
(44171, 'Deuteronomy 7:4', 'Deuteronomy', 7, 4, 'ځکه چې بیا به هغوی ستاسو اولادونه د څښتن څخه د نورو خدایانو عبادت ته راواړوي. که چېرې داسې وشي، نو څښتن به په تاسو باندې په قهر شي او تاسو به زر له منځه یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_4.mp3', '', 1761754199, 1761754199),
(44172, 'Deuteronomy 7:5', 'Deuteronomy', 7, 5, 'نو بیا داسې وکړئ چې د هغوی د قربانۍ ځایونه راوغورځوئ، هغه لویې تیږې چې د هغوی د عبادت دپاره کارول کیږي ټوټې ټوټې کړئ، د اشیره بتان یې راچپه کړئ او نور بتان یې وسوځوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_5.mp3', '', 1761754199, 1761754199),
(44173, 'Deuteronomy 7:6', 'Deuteronomy', 7, 6, 'داسې کار وکړئ، ځکه چې تاسو د خپل څښتن خدای سپېڅلي خلک یئ. هغه د ځمکې په مخ د ټولو قومونو څخه تاسو د خپل ځانګړي قوم په توګه غوره کړي یئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_6.mp3', '', 1761754199, 1761754199),
(44174, 'Deuteronomy 7:7', 'Deuteronomy', 7, 7, 'څښتن د دې په خاطر ستاسو سره مینه نه کوله او د دې په خاطر یې تاسو غوره کړي نه یئ چې ستاسو شمېر د نورو قومونو څخه زیات ؤ، بلکې ستاسو قوم د ځمکې پر مخ تر ټولو کوچنی قوم ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_7.mp3', '', 1761754199, 1761754199),
(44175, 'Deuteronomy 7:8', 'Deuteronomy', 7, 8, 'خو څښتن ستاسو سره مینه کوله او غوښتل یې چې په هغې وعدې باندې ودریږي چې ستاسو د نیکونو سره یې کړې وه. نو په دې خاطر هغه تاسو په خپل قوي مټ سره وژغورلئ او د مصر د پاچا فرعون د غلامۍ څخه یې ازاد کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_8.mp3', '', 1761754199, 1761754199),
(44176, 'Deuteronomy 7:9', 'Deuteronomy', 7, 9, 'زه ستاسو څخه غواړم په دې پوه شئ چې هغه څښتن خدای چې عبادت یې کوئ هغه رښتینی او وفادار خدای دی. هغه به په خپل لوظ باندې ولاړ وي او خپله تلپاتې مینه به د هغو خلکو زرو نسلونو ته وښایي چې د هغه سره مینه کوي او د حکمونو اطاعت یې کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_9.mp3', '', 1761754199, 1761754199),
(44177, 'Deuteronomy 7:10', 'Deuteronomy', 7, 10, 'خو هغه خلک چې د هغه څخه کرکه کوي، هغوی ته به زر داسې سزا ورکړي چې تباه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_10.mp3', '', 1761754199, 1761754199),
(44178, 'Deuteronomy 7:11', 'Deuteronomy', 7, 11, 'نو اوس په غور سره د هغو ټولو قوانینو څخه چې نن مې تاسو ته درکړل، پیروي وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_11.mp3', '', 1761754199, 1761754199),
(44179, 'Deuteronomy 7:12', 'Deuteronomy', 7, 12, 'که چېرې تاسو دغو امرونو ته غوږ ونیسئ او په وفادارۍ سره د هغو اطاعت وکړئ، بیا به ستاسو څښتن خدای لکه څنګه یې چې زمونږ د نیکونو سره وعده کړې ده په خپل هغه لوظ باندې ودریږي چې ستاسو سره یې کړی دی او هغه به ستاسو سره په دوامداره توګه مینه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_12.mp3', '', 1761754199, 1761754199),
(44180, 'Deuteronomy 7:13', 'Deuteronomy', 7, 13, 'هغه به ستاسو سره مینه وکړي او برکت به درکړي، ترڅو ستاسو شمېر زیات شي او ډېر اولادونه مو پیدا شي. ستاسو په پټیو کې به برکت واچوي، ترڅو تاسو غلې دانې، شراب او د زیتونو تېل ولرئ او د ډېرو پادو او رمو په درکولو سره به تاسو ته برکت درکړي. هغه به دا ټول برکتونه په هغه خاوره کې درکړي چې زمونږ د نیکونو سره یې وعده کړې وه چې تاسو ته به یې درکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_13.mp3', '', 1761754199, 1761754199),
(44181, 'Deuteronomy 7:14', 'Deuteronomy', 7, 14, 'په نړۍ کې به د هېڅ قوم سره ستاسو په شان زیات برکت نه وي. ستاسو او ستاسو د حیواناتو څخه به هېڅ یو شنډ نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_14.mp3', '', 1761754199, 1761754199),
(44182, 'Deuteronomy 7:15', 'Deuteronomy', 7, 15, 'څښتن به تاسو د ټولو ناروغیو څخه وساتي او هغه به تاسو په هېڅ داسې وېروونکې ناروغۍ باندې اخته نه کړي چې په مصر کې ورسره بلد وئ، بلکې ستاسو ټول دښمنان به ورباندې اخته کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_15.mp3', '', 1761754199, 1761754199),
(44183, 'Deuteronomy 7:16', 'Deuteronomy', 7, 16, 'هغه به ټول قومونه له منځه یوسي چې خپل څښتن خدای به یې تاسو ته په لاس درکړي او په هغوی باندې هېڅ رحم مه کوئ. د هغوی د خدایانو عبادت مه کوئ، ځکه چې دا به ستاسو دپاره یو وژونکی دام وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_16.mp3', '', 1761754199, 1761754199),
(44184, 'Deuteronomy 7:17', 'Deuteronomy', 7, 17, 'د ځان سره داسې مه وایئ چې د دې قومونو شمېر زمونږ څخه زیات دی او مونږ هغوی شړلی نه شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_17.mp3', '', 1761754199, 1761754199),
(44185, 'Deuteronomy 7:18', 'Deuteronomy', 7, 18, 'د هغوی څخه مه وېرېږئ. هغه کارونه په یاد ساتئ چې ستاسو څښتن خدای په فرعون او د مصر په ټولو خلکو باندې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_18.mp3', '', 1761754199, 1761754199),
(44186, 'Deuteronomy 7:19', 'Deuteronomy', 7, 19, 'هغه هیبتناکه بلاګانې په یاد ساتئ چې تاسو په خپلو سترګو ولیدلې، هغه معجزې او عجیبه عجیبه کارونه او هغه قوي مټ او ټول قدرت چې ستاسو څښتن خدای تاسو ورباندې ازاد کړئ. هغه به په هماغه ډول چې مصریان یې تباه کړل، دا ټول قومونه به چې تاسو اوس ورڅخه وېرېږئ، هم تباه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_19.mp3', '', 1761754199, 1761754199),
(44187, 'Deuteronomy 7:20', 'Deuteronomy', 7, 20, 'هغه به حتی د هغوی په منځ کې سخته وېره پیدا کړي او هغه ټول خلک به له منځه یوسي چې تښتي او پټیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_20.mp3', '', 1761754199, 1761754199),
(44188, 'Deuteronomy 7:21', 'Deuteronomy', 7, 21, 'نو د دغو خلکو څخه مه وېرېږئ، ځکه چې ستاسو څښتن خدای ستاسو سره مل دی. هغه لوی او هیبتناکه خدای دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_21.mp3', '', 1761754199, 1761754199),
(44189, 'Deuteronomy 7:22', 'Deuteronomy', 7, 22, 'ستاسو څښتن خدای به دا قومونه ورو ورو ستاسو له مخې څخه لېرې کړي. تاسو به ونه شئ کولای چې هغوی په یو وار سره له منځه یوسئ، ځکه که چېرې داسې وکړئ، د وحشي حیواناتو شمېر به زیات شي او دا به تاسو ته د خطر سبب وګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_22.mp3', '', 1761754199, 1761754199),
(44190, 'Deuteronomy 7:23', 'Deuteronomy', 7, 23, 'څښتن به تاسو ته خپل دښمنان په لاس درکړي او په هغوی باندې به داسې سخته وېره راولي، ترڅو چې تباه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_23.mp3', '', 1761754199, 1761754199),
(44191, 'Deuteronomy 7:24', 'Deuteronomy', 7, 24, 'هغه به د هغوی پاچاهان تاسو ته په لاس درکړي او تاسو به د هغوی نوم او نښان د ځمکې د مخ څخه ورک کړئ. هېڅوک به ونه شي کولای چې ستاسو په وړاندې ودریږي، تاسو به هغوی له منځه یوسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_24.mp3', '', 1761754199, 1761754199),
(44192, 'Deuteronomy 7:25', 'Deuteronomy', 7, 25, 'د هغوی بتان وسوځوئ. هغو سرو او سپینو زرو ته چې دا بتان ورڅخه جوړ شوي دي، تمه مه کوئ او هغه د خپلو ځانونو دپاره مه اخلئ. که چېرې داسې وکړئ، دا به وژونکی دام وي، ځکه چې څښتن د بت پرستۍ څخه کرکه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_25.mp3', '', 1761754199, 1761754199),
(44193, 'Deuteronomy 7:26', 'Deuteronomy', 7, 26, 'د دغو بتانو څخه هېڅ یو یې خپلو کورونو ته مه راوړئ. که نه، نو په تاسو باندې به هم هماغسې لعنت وویل شي لکه څنګه چې په هغو باندې ویل شوی دی. تاسو باید له دغو بتانو څخه کرکه وکړئ او په سپکه سترګه ورته وګورئ، ځکه چې په هغو باندې د څښتن لعنت ویل شوی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy7_verse_26.mp3', '', 1761754199, 1761754199),
(44194, 'Malachi 3:1', 'Malachi', 3, 1, '”ګوره، زۀ خپل پېغمبر ستا نه وړاندې لېږم چې ستا مخې ته لاره تياره کړى. بيا به ناڅاپه هغه مالِک چې تاسو يې لټون کوئ خپل کور ته راشى، هغه د لوظ پېغام راوړونکے به راشى د چا چې تاسو ليواله يئ،“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi3_verse_1.mp3', '', 1761754199, 1761754199),
(44195, 'Malachi 3:2', 'Malachi', 3, 2, 'خو د هغۀ د راتلو ورځ څوک برداشت کولے شى؟ څوک ودرېدلے شى کله چې هغه راښکاره شى؟ ځکه چې هغه به لکه د صفا کوونکى اور يا د دهوبى د صابون په شان وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi3_verse_2.mp3', '', 1761754199, 1761754199),
(44196, 'Malachi 3:3', 'Malachi', 3, 3, 'هغه به لکه د سپينو زرو د صفا کوونکى او خالص کوونکى په شان کښېنى، هغه به ليويان صفا کړى او د سرو او سپينو زرو په شان به يې چاڼ کړى. بيا به دوئ صادقان شى چې مالِک خُدائ ته به نذرانې پېش کولے شى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi3_verse_3.mp3', '', 1761754199, 1761754199),
(44197, 'Malachi 3:4', 'Malachi', 3, 4, 'او د يهوداه او يروشلم نذرانې به مالِک خُدائ ته د قبلولو وى، داسې لکه چې په تېرو ورځو، او په تېر شوو کالونو کښې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi3_verse_4.mp3', '', 1761754199, 1761754199),
(44198, 'Malachi 3:5', 'Malachi', 3, 5, '”نو زۀ به تاسو له د عدالت دپاره نزدې درشم. زر به زۀ د جادوګرو، زناکارو او چې په دروغو قسم خورى د هغوئ خلاف ګواهى ورکړم، د هغوئ خلاف چې د مزدورانو سره په مزدورۍ کښې ټګى کوى، څوک چې په کونډو او يتيمانانو ظلم کوى، او مسافر د اِنصاف نه محروموى خو زما نه نۀ يريږى،“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi3_verse_5.mp3', '', 1761754199, 1761754199),
(44199, 'Malachi 3:6', 'Malachi', 3, 6, '”زۀ نۀ بدلېدونکے مالِک خُدائ يم. نو ځکه تاسو، اے د يعقوب اولاده، تباه نۀ شوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi3_verse_6.mp3', '', 1761754199, 1761754199),
(44200, 'Malachi 3:7', 'Malachi', 3, 7, 'ستاسو د پلار نيکونو د وخت نه تاسو زما د احکامو نه اوړېدلې يئ او عمل مو پرې نۀ دے کړے. ما ته راوګرځئ، او زۀ به تاسو ته راوګرځم،“ مالِک خُدائ ربُ الافواج فرمائى. ”خو تاسو تپوس کوئ، مونږ څنګه راوګرځُو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi3_verse_7.mp3', '', 1761754199, 1761754199),
(44201, 'Malachi 3:8', 'Malachi', 3, 8, 'خو زۀ وايم چې، ولې يو سړے د خُدائ پاک نه غلا کولے شى څۀ؟ خو باوجود د دې تاسو زما نه غلا کوئ. خو بيا تاسو تپوس کوئ چې، مونږ تا نه څنګه غلا کوُو؟ خو زۀ دا وايم چې، تاسو په لسمه حِصه او نذرانو کښې زما نه غلا کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi3_verse_8.mp3', '', 1761754199, 1761754199),
(44202, 'Malachi 3:9', 'Malachi', 3, 9, 'په تاسو او ستاسو په ټول قوم لعنت دے، ځکه چې تاسو ما نه غلا کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi3_verse_9.mp3', '', 1761754199, 1761754199),
(44203, 'Malachi 3:10', 'Malachi', 3, 10, 'خپله ټوله لسمه حِصه زما ګودام ته راوړئ، چې زما په کور کښې غله دانه وى. په خپل دې کار سره ما وآزمايئ،“ مالِک خُدائ ربُ الافواج فرمائى، ”نو تاسو به ګورئ چې زۀ درته د آسمان نه د باران دروازې خلاصى کړم او په تاسو به دومره ډېر نعمتونه راوروم چې بيا به تاسو سره د دې دپاره د کېښودو ځائ نۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi3_verse_10.mp3', '', 1761754199, 1761754199),
(44204, 'Malachi 3:11', 'Malachi', 3, 11, 'زۀ به ستاسو فصلونه د وبا او مُولخانو د تباه کولو نه وساتم، او ستاسو په پټو کښې به د انګورو بوټى، انګور د پخېدلو نه وړاندې نۀ غورزوى،“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi3_verse_11.mp3', '', 1761754199, 1761754199),
(44205, 'Malachi 3:12', 'Malachi', 3, 12, '”بيا به ټول قومونه تاسو ته بختور وائى، ځکه چې تاسو به يو ښاد او آباد مُلک يئ،“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi3_verse_12.mp3', '', 1761754199, 1761754199),
(44206, 'Malachi 3:13', 'Malachi', 3, 13, 'مالِک خُدائ فرمائى چې، ”تاسو زما په حقله سپکې سپورې خبرې وکړې،“ ”خو اوس تاسو تپوس کوئ چې، مونږ ستا خلاف څۀ وئيلى دى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi3_verse_13.mp3', '', 1761754199, 1761754199),
(44207, 'Malachi 3:14', 'Malachi', 3, 14, 'تاسو ووئيل چې، د خُدائ پاک خِدمت کول بې‌فائدې دى. مونږ د هغۀ د حکمونو په منلو او د مالِک خُدائ ربُ الافواج په حضور کښې په خپلو ګناهونو په ماتم کولو څۀ حاصل کړل؟ نه، هيڅ نه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi3_verse_14.mp3', '', 1761754199, 1761754199),
(44208, 'Malachi 3:15', 'Malachi', 3, 15, 'نو اوس مونږ مغروره خلقو ته بختور وايو. يقيناً چې بدعمله خلق ترقى کوى، او تر دې چې هغوئ څوک چې د خُدائ پاک مقابله کوى سزا نۀ ګورى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi3_verse_15.mp3', '', 1761754199, 1761754199),
(44209, 'Malachi 3:16', 'Malachi', 3, 16, 'د دې نه وروستو، بيا کوم کسان چې د مالِک خُدائ نه يرېدل يو بل سره يې خبرې وکړې، او مالِک خُدائ ورته غوږ شو او هغه يې واورېدلې. د هغۀ په حضور کښې يو يادګارى طومار ليکلے شوے وو د هغوئ د نومونو په حقله څوک چې د مالِک خُدائ نه يرېدل او د هغۀ د نوم عزت يې کولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi3_verse_16.mp3', '', 1761754199, 1761754199),
(44210, 'Malachi 3:17', 'Malachi', 3, 17, 'مالِک خُدائ ربُ الافواج فرمائى، ”هغوئ به زما وى. په هغه ورځ کله چې زۀ هغوئ خپل خاص ملکيت جوړوم، زۀ به هغوئ سره همدردى وکړم، لکه څنګه چې يو کس د خپل هغه زوئ سره همدردى کوى څوک چې د هغۀ خِدمت کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi3_verse_17.mp3', '', 1761754199, 1761754199);